(async () => {
  // 检查 args[0] 是否为 "off"，表示效果被删除
  if (args[0] !== "off") {
    console.log("❌ 宏未触发：args[0] 不是 'off'，当前值为", args[0]);
    return;
  }

  // 获取目标 Token 和 Actor
  const tokenId = args[1]?.tokenId || args[1]?.token?.id;
  const token = canvas.tokens.get(tokenId);
  const actor = token?.actor;
  if (!actor) {
    console.log("❌ 未找到目标 Actor，无法继续执行宏");
    return;
  }

  console.log("✅ 成功获取 Actor：", actor.name);

  // 查找名为“艾伐黑触手 Black Tentacles (In Aura)”的效果
  const auraEffect = actor.effects.find(e => e.label === "艾伐黑触手 Black Tentacles (In Aura)");
  if (!auraEffect) {
    console.log("⚠️ 未找到 '艾伐黑触手 Black Tentacles (In Aura)' 效果");
    return;
  }

  // 删除该效果
  await auraEffect.delete();
  console.log("🧹 已成功删除 '艾伐黑触手 Black Tentacles (In Aura)' 效果");
})();
